INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('cop31-gescheitert-klimakonferenz-antalya-oesterreich-totschnig','COP31 gescheitert: Klimagipfel ohne Fossil-Ausstieg','Nach mehr als 49 Stunden Verlängerung ist die Weltklimakonferenz COP31 in Antalya ohne Abschlusserklärung zu Ende gegangen. Die EU legte Widerspruch ein, Umweltminister Totschnig spricht von einem Rückschritt.','Die COP31 ist gescheitert: Die UN-Weltklimakonferenz im türkischen Antalya ist am Sonntagabend ohne gemeinsames Abschlussdokument zu Ende gegangen. Nach einer Rekordverlängerung von mehr als 49 Stunden konnten sich die Staaten nicht auf einen Text einigen. Zuletzt war eine UN-Klimaverhandlung in dieser Form 2009 in Kopenhagen gescheitert.

Eigentlich hätte der Gipfel, den die Türkei gemeinsam mit Australien leitete, bereits am Freitag enden sollen. Das Schlussplenum begann nach mehreren Verschiebungen erst am Sonntag zu Mittag, besiegelt wurde das Ende gegen 19.30 Uhr Ortszeit.

## Warum die COP31 gescheitert ist

Kern des Streits war die Frage, wie klar sich die Staatengemeinschaft zum Abschied von Kohle, Öl und Gas bekennt. Der rund zehnseitige Entwurf der Konferenzleitung erwähnte fossile Energieträger nicht ausdrücklich. Er enthielt lediglich einen allgemeinen Verweis auf den Beschluss der Klimakonferenz von Dubai 2023, wonach sich die Welt schrittweise von fossilen Energien abwenden soll.

Für die Europäische Union war das zu wenig. Im Plenum legte sie formell Widerspruch gegen den Text ein. Auch Panama und die Marshallinseln lehnten ihn wegen mangelnden Ehrgeizes ab, ebenso mehrere afrikanische Staaten, kleine Inselstaaten und am wenigsten entwickelte Länder. Deutschland und Frankreich hatten den Entwurf schon vor der Schlusssitzung als nicht zustimmungsfähig bezeichnet.

Auf der anderen Seite standen erdölfördernde Staaten. Russland lehnte jede Formulierung zu fossilen Brennstoffen ab und warnte vor Preisschocks. Saudi-Arabien verlangte, dass auch Technologien zur CO2-Abscheidung und -Speicherung als Lösung gelten. Weil bei UN-Klimakonferenzen Konsens nötig ist, reichte der Widerstand weniger Länder, obwohl sich laut Berichten mehr als 130 Staaten für einen Ausstieg aus fossilen Energien ausgesprochen hatten.

## Österreichs Position: Totschnig sagt Nein

Umweltminister Norbert Totschnig (ÖVP) nannte den Entwurf sehr enttäuschend und einen Rückschritt. Der Text blende die Realität aus und rede fossile Brennstoffe schön, obwohl gerade diese die Erderwärmung antreiben. Einige wenige Staaten würden Fortschritt auf Kosten der Lebensqualität aller blockieren. Seine Botschaft: „Wir stimmen diesem Rückschritt nicht zu.“

Österreich wolle sich davon nicht bremsen lassen und den Umstieg auf Photovoltaik, Wasserkraft, Wind und Biomasse sowie die Elektrifizierung weiter vorantreiben. Wie es um die heimischen Ziele steht, zeigt die laufende Debatte um das [neue Klimagesetz in Österreich](/artikel/klimagesetz-oesterreich-begutachtung-endet-standortklausel-kritik). Laut Umweltministerium scheiterte die Konferenz übrigens nicht an der Klimafinanzierung, sondern an der Frage der fossilen Energien.

## Was von der Klimakonferenz bleibt

Ganz ohne Ergebnis endet Antalya dennoch nicht. Außerhalb des offiziellen Beschlusses gab es mehrere Initiativen einzelner Staatengruppen:

- Rund 30 Staaten haben eigene Pläne für den Ausstieg aus Kohle, Öl und Gas vorgelegt oder angekündigt.
- Im Juli wollen sich Dutzende Länder in Tuvalu erneut zum Fossilausstieg abstimmen.
- Eine Initiative der türkischen Präsidentschaft sieht vor, den Stromanteil am weltweiten Endenergieverbrauch von 23 auf 35 Prozent zu erhöhen.
- Die EU, Deutschland und zwölf weitere Staaten wollen stärker gegen das Treibhausgas SF6 vorgehen.

## Reaktionen aus Österreich

Umweltorganisationen sehen das Ende mit gemischten Gefühlen. Der WWF Österreich sprach von einem verheerenden Scheitern, Greenpeace kritisierte, die Staaten seien nur mit roten Linien angereist. Die Allianz für Klimagerechtigkeit forderte von EU und Österreich, sich für die nächste Konferenz besser vorzubereiten, eigene Ausstiegspläne zu erarbeiten und mehr Geld für den Globalen Süden bereitzustellen. Mehrere Organisationen betonten zugleich, dass kein Beschluss besser sei als einer, der die fossile Industrie stärkt.

Die Grünen forderten, Übergewinne fossiler Konzerne abzuschöpfen. Die FPÖ wertete das Ergebnis dagegen als Absage des Rests der Welt an den Klimakurs der EU. UN-Generalsekretär António Guterres zeigte sich tief enttäuscht. Laut UN-Berechnungen steuert die Welt derzeit auf eine Erwärmung von rund 2,8 Grad bis Ende des Jahrhunderts zu. Wie stark Österreich selbst noch von fossilen Importen abhängt, zeigt der [Kompass zur Energieunabhängigkeit](/artikel/energieunabhaengigkeit-oesterreich-kompass-fossile-importe).','energie','Klima',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/cop31-gescheitert-klimakonferenz-antalya-oesterreich-totschnig.webp','ORF','https://orf.at/stories/3448942/','published','2026-11-23T11:43:00.000Z','2026-11-23T11:44:14.947Z','COP31 gescheitert: Was das für Österreich heißt','COP31 gescheitert: Die Weltklimakonferenz in Antalya endete ohne Abschlusstext. Warum EU und Österreich Nein sagten und welche Ergebnisse bleiben.','COP31 gescheitert','["COP31","COP31 gescheitert","Weltklimakonferenz Antalya","Klimakonferenz 2026","Totschnig COP31","fossile Brennstoffe Ausstieg","Klimaschutz Österreich","UN-Klimagipfel Ergebnis"]','COP31 gescheitert: leerer Plenarsaal nach der Weltklimakonferenz in Antalya','Empty large international conference plenary hall at dusk after a session ended, rows of vacant delegate desks with scattered papers and headsets, warm Mediterranean evening light through tall windows, a lone cleaner''s cart in the aisle, sense of unfinished negotiations, no text, no logos, no readable signs, no people''s faces','[{"q":"Warum ist die COP31 gescheitert?","a":"Der Entwurf der Konferenzleitung erwähnte Kohle, Öl und Gas nicht ausdrücklich. Die EU und weitere Staaten legten Widerspruch ein, Ölstaaten wie Russland und Saudi-Arabien lehnten schärfere Formulierungen ab."},{"q":"Wie hat sich Österreich bei der COP31 positioniert?","a":"Umweltminister Norbert Totschnig nannte den Text einen Rückschritt und erklärte, Österreich stimme ihm nicht zu. Der Ausbau erneuerbarer Energien im Inland soll weitergehen."},{"q":"Gibt es trotzdem Ergebnisse aus Antalya?","a":"Ja, freiwillige Initiativen: rund 30 Staaten mit Ausstiegsplänen für fossile Energien, ein Folgetreffen in Tuvalu im Juli und eine Initiative für mehr Strom im Energiemix."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
